import re
from collections import defaultdict

def parse_auth_log(log_file):
    """Parse SSH auth.log lines and report failed login attempts by IP."""
    failed_attempts = defaultdict(int)
    # Pattern to match failed password attempts for SSH
    pattern = re.compile(r'Failed password for .* from (\d+\.\d+\.\d+\.\d+)')

    try:
        with open(log_file, 'r') as f:
            for line in f:
                match = pattern.search(line)
                if match:
                    ip = match.group(1)
                    failed_attempts[ip] += 1
    except FileNotFoundError:
        print(f"Error: File '{log_file}' not found.")
        return {}
    except PermissionError:
        print(f"Error: Permission denied when accessing '{log_file}'.")
        return {}

    return failed_attempts

def report_failed_attempts(failed_attempts):
    """Report failed login attempts by IP, sorted by count descending."""
    if not failed_attempts:
        print("No failed login attempts found.")
        return

    sorted_attempts = sorted(failed_attempts.items(), key=lambda x: x[1], reverse=True)
    print("Failed SSH Login Attempts by IP:")
    print("-" * 30)
    for ip, count in sorted_attempts:
        print(f"IP: {ip:<15} Attempts: {count}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python ssh_failed_logins.py <auth_log_file>")
        sys.exit(1)

    log_file = sys.argv[1]
    failed_attempts = parse_auth_log(log_file)
    report_failed_attempts(failed_attempts)
